const T=[
 {id:"texto",practica:"fr-quefalla",esquema:{titol:"A-Co-Co: las tres propiedades",html:"<div class='esq-col' style='grid-template-columns:1fr 1fr 1fr'><div style='background:#fef3c7'><b>Adecuación</b><br>¿a quién le hablo?</div><div style='background:#dbeafe'><b>Coherencia</b><br>¿de qué y en qué orden?</div><div style='background:#dcfce7'><b>Cohesión</b><br>¿con qué lo uno? (conectores)</div></div>"},frases:"fr-texto",ic:"📄",col:"#dc2626",titol:"El texto y sus propiedades",font:"Tema 2 · p. 16",
  idea:"Un texto es un mensaje, oral o escrito, con sentido completo. Para funcionar tiene que ser adecuado, coherente y cohesionado.",
  pts:["Un texto puede ser <b>una sola palabra</b> («¡Cuidado!»), una oración, un párrafo, un cuento, un poema...",
   "<b>Adecuación</b>: se adapta a la situación: a <b>quién</b> va dirigido y con qué <b>intención</b>.",
   "<b>Coherencia</b>: tiene un <b>tema definido</b> y la información va en un <b>orden lógico</b>.",
   "<b>Cohesión</b>: las partes están <b>relacionadas</b> entre sí. Para eso usamos los <b>conectores</b>.",
   "Conectores para añadir o contrastar: <b>además, sin embargo, no obstante, por lo tanto</b>.",
   "Para explicar con otras palabras: <b>es decir, esto es, mejor dicho</b>. Para ordenar o poner ejemplos: <b>a continuación, para terminar, por ejemplo</b>."],
  truc:"A-Co-Co: Adecuación (¿a quién le hablo?), Coherencia (¿de qué hablo y en qué orden?), Cohesión (¿con qué pegamento uno las frases?). Los conectores son el pegamento.",
  compte:"Que un texto sea corto no significa que no sea un texto. «¡Cuidado!» ya es un texto completo.",
  fc:[["¿Qué es un texto?","Un mensaje oral o escrito con sentido completo."],["Las tres propiedades del texto","Adecuación, coherencia y cohesión."],["Adecuación","Adaptarse a quién lo recibe y a la intención."],["Coherencia","Tema definido y orden lógico."],["Cohesión","Las partes están unidas, sobre todo con conectores."],["Un conector para explicar algo con otras palabras","Es decir (o esto es, mejor dicho)."]],
  q:[["Un texto tiene un tema definido y la información va en orden lógico. ¿Qué propiedad cumple?",["La coherencia","La adecuación","La cohesión"],0,"Coherencia = tema claro y orden lógico."],
     ["Escribes al director como si fuera tu colega de clase. ¿Qué propiedad fallas?",["La cohesión","La adecuación","La coherencia"],1,"La adecuación mira a quién va dirigido el texto."],
     ["¿Puede ser un texto una sola palabra?",["Sí, si tiene sentido completo","No, nunca","Solo si es un poema"],0,"«¡Cuidado!» es un texto completo."],
     ["¿Para qué sirven los conectores?",["Para unir las partes del texto","Para poner el título","Para separar sílabas"],0,"Dan cohesión: son el pegamento del texto."],
     ["¿Cuál de estos conectores sirve para explicar algo con otras palabras?",["Sin embargo","Es decir","Además"],1,"Sin embargo contrasta; además añade."],
     ["«Me gusta el fútbol. Además, juego en un equipo.» ¿Para qué sirve «además»?",["Para explicar con otras palabras","Para terminar el texto","Para añadir información"],2,"«Además» añade algo más a lo que ya has dicho."],
     ["¿Cuáles son las tres propiedades del texto?",["Narración, descripción y argumentación","Adecuación, coherencia y cohesión","Título, párrafos y punto final"],1,"Recuerda el truco A-Co-Co: adecuación, coherencia y cohesión."],
     ["Un texto salta de tu perro a la Luna y luego a una receta, sin ningún orden. ¿Qué propiedad le falta?",["La adecuación","La cohesión","La coherencia"],2,"Sin un tema definido ni un orden lógico, falla la coherencia."]]},
 {id:"tipos",frases:"fr-texto",ic:"🗂️",col:"#ea580c",titol:"Los tipos de textos",font:"Tema 2 · p. 16",
  idea:"Según lo que quieren conseguir, hay siete tipos de textos.",
  pts:["<b>Narrativo</b>: cuenta hechos en un lugar y un tiempo (un cuento).","<b>Descriptivo</b>: explica cómo es algo o alguien (el retrato de tu perro).",
   "<b>Dialogado</b>: dos o más personas intercambian información (una entrevista).","<b>Expositivo</b>: informa sobre un tema para darlo a conocer (tu libro de Naturales).",
   "<b>Argumentativo</b>: da opiniones e intenta convencer (un artículo de opinión).","<b>Instructivo</b>: aconseja cómo hacer algo (una receta).","<b>Predictivo</b>: predice hechos futuros (el tiempo de mañana)."],
  truc:"«Nos Dan Dos Exámenes; Ay, Igual Pasamos»: Narrativo, Descriptivo, Dialogado, Expositivo, Argumentativo, Instructivo, Predictivo.",
  compte:"Expositivo informa; argumentativo opina y quiere convencer. No es lo mismo.",
  fc:[["¿Cuántos tipos de textos hay?","Siete."],["Una receta es un texto...","Instructivo."],["El pronóstico del tiempo es un texto...","Predictivo."],["Un texto que quiere convencerte es...","Argumentativo."],["Una entrevista es un texto...","Dialogado."]],
  q:[["Una receta de cocina es un texto...",["Instructivo","Narrativo","Predictivo"],0,"Aconseja cómo hacer algo."],
     ["«Mañana lloverá en el Pirineo.» ¿Qué tipo de texto es?",["Expositivo","Predictivo","Descriptivo"],1,"Predice un hecho futuro."],
     ["Un artículo que intenta convencerte de no usar el móvil en la cena es...",["Expositivo","Argumentativo","Dialogado"],1,"Da opiniones y argumentos para convencer."],
     ["Tu libro de Naturales es sobre todo un texto...",["Expositivo","Narrativo","Instructivo"],0,"Informa sobre un tema para darlo a conocer."],
     ["Un texto que explica cómo es tu abuela, eligiendo sus detalles, es...",["Narrativo","Descriptivo","Argumentativo"],1,"Describir = decir cómo es algo o alguien."],
     ["Una entrevista a una futbolista en la revista del instituto es un texto...",["Dialogado","Expositivo","Narrativo"],0,"Dos personas intercambian información: es dialogado."],
     ["Un cuento que pasa en un bosque una noche de invierno es un texto...",["Descriptivo","Instructivo","Narrativo"],2,"Cuenta hechos en un lugar y un tiempo: es narrativo."],
     ["Según lo que quieren conseguir, ¿cuántos tipos de textos hay?",["Cinco","Siete","Tres"],1,"Son siete: «Nos Dan Dos Exámenes; Ay, Igual Pasamos»."]]},
 {id:"sustantivo",practica:"mc-sustantivos",esquema:{titol:"¿Concreto o abstracto?",marca:{t:"El rebaño cruzó el puente con alegría",m:"-C--C-A"},joc:"mc-sustantivos"},frases:"fr-sustantivo",ic:"🏷️",col:"#d97706",titol:"El sustantivo y sus clases",font:"Tema 2 · p. 56",
  idea:"El sustantivo nombra personas, lugares, animales, cosas o ideas, y sus clases van por parejas.",
  pts:["<b>Propios</b>: nombran a un ser único y van con <b>mayúscula</b> (Tarragona, Ebro, Carmen). <b>Comunes</b>: nombran a cualquiera de una clase (ciudad, río, niña).",
   "<b>Topónimos</b> = nombres propios de lugar (Pirineos, Barcelona). <b>Antropónimos</b> = nombres propios de persona (Alba, Raúl).",
   "<b>Individuales</b>: en singular nombran a uno solo (abeja, barco, pino). <b>Colectivos</b>: en singular nombran a un grupo (enjambre, flota, pinar).",
   "<b>Concretos</b>: se pueden ver, tocar, oír (lápiz, perro, montaña). <b>Abstractos</b>: ideas o sentimientos (amor, pereza, sensibilidad).",
   "Para subrayar sustantivos, subraya <b>solo el sustantivo</b>: no el artículo (la, el) ni el adjetivo (cubiertas, pequeña)."],
  truc:"Tres preguntas: ¿único o de una clase? ¿uno o un grupo? ¿se toca o se piensa? Topo-nimo = lugar (el topo vive en un lugar). Antropo-nimo = persona.",
  compte:"Un colectivo NO es abstracto: un rebaño o un ejército se pueden ver. Y en el cuaderno se colaron artículos y adjetivos al subrayar sustantivos: solo el sustantivo.",
  fc:[["¿Qué es un sustantivo colectivo?","El que nombra en singular a un grupo (enjambre, flota)."],["Colectivo de «ovejas»","Rebaño."],["¿Qué es un topónimo?","El nombre propio de un lugar (Barcelona)."],["¿Qué es un antropónimo?","El nombre propio de una persona (Raúl)."],["«Pereza»: ¿concreto o abstracto?","Abstracto."],["¿Cómo se escriben los propios?","Con mayúscula inicial."]],
  q:[["«Flota» es un sustantivo...",["Individual","Colectivo","Propio"],1,"Nombra en singular a un conjunto de barcos."],
     ["¿Cuál de estos sustantivos es abstracto?",["pared","pereza","pato"],1,"La pereza no se puede ver ni tocar."],
     ["¿Cómo se llaman los nombres propios de persona?",["Topónimos","Antropónimos","Colectivos"],1,"Antropónimo = persona; topónimo = lugar."],
     ["«Un rebaño de ovejas.» ¿«Rebaño» es concreto o abstracto?",["Abstracto, porque es un grupo","Concreto, porque se puede ver","Ni uno ni otro"],1,"Que sea colectivo no lo hace abstracto."],
     ["En «Las montañas se extendían cubiertas de nieve», ¿qué palabras son sustantivos?",["montañas y nieve","las, montañas y cubiertas","cubiertas y nieve"],0,"«Las» es un artículo y «cubiertas» un adjetivo."],
     ["«Ebro» es un sustantivo...",["común","propio","colectivo"],1,"Nombra un río único y va con mayúscula."],
     ["¿Qué palabra es un topónimo?",["Raúl","ciudad","Pirineos"],2,"Es el nombre propio de un lugar. Raúl es un antropónimo y ciudad es común."],
     ["¿Cuál es el colectivo de «abeja»?",["panal","enjambre","abejorro"],1,"El enjambre es el grupo de abejas; el panal es donde guardan la miel."]]},
 {id:"genero",practica:"fr-interferencias",esquema:{titol:"Trampas del catalán",html:"<table><tr><th>Catalán</th><th>Castellano</th></tr><tr><td>la dent</td><td class='ex'>el diente</td></tr><tr><td>el costum</td><td class='ex'>la costumbre</td></tr><tr><td>el senyal</td><td class='ex'>la señal</td></tr><tr><td>les postres</td><td class='ex'>el postre</td></tr><tr><td>els llapis</td><td class='ex'>los lápices</td></tr></table>"},frases:"fr-sustantivo",ic:"⚖️",col:"#ca8a04",titol:"Género, número y concordancia",font:"Tema 2 · p. 57",
  idea:"El sustantivo tiene género y número, y el determinante y el adjetivo tienen que concordar con él.",
  pts:["<b>Terminación variable</b>: chico/chica, jefe/jefa, escritor/escritora, actor/<b>actriz</b>, alcalde/<b>alcaldesa</b>.",
   "<b>Heterónimos</b> (palabras distintas): hombre/mujer, caballo/yegua.","<b>Invariables</b> (lo marca el artículo): el/la pianista, el/la periodista, el/la testigo. Animales: la víbora macho.",
   "<b>Plural</b>: -s o -es (casas, cárceles). Sin cambio: el/los atlas, la/las crisis. Club → clubes; ley → leyes; jersey → jerséis.",
   "<b>Concordancia</b>: mismo género y número: la actriz famosa, unos gatos negros.",
   "Ojo con el catalán: <b>el</b> calor, <b>el</b> olor, <b>la</b> costumbre, <b>el</b> diente, <b>la</b> nariz, <b>la</b> señal."],
  truc:"En «el atlas» o «la crisis» la palabra no cambia: el chivato es el artículo.",
  compte:"Barón → baronesa, y al revés baronesa → barón (no «barones», que es el plural).",
  fc:[["Femenino de «actor»","Actriz."],["Femenino de «caballo» (¿qué tipo es?)","Yegua: heterónimo."],["Femenino de «el pianista»","La pianista (invariable)."],["Plural de «crisis»","Las crisis (no cambia)."],["Masculino de «baronesa»","Barón."],["¿Qué es la concordancia?","Que sustantivo, determinante y adjetivo tengan el mismo género y número."]],
  q:[["El femenino de «caballo» es «yegua». ¿Qué tipo de cambio es?",["Terminación variable","Heterónimo","Invariable"],1,"Son palabras totalmente distintas."],
     ["¿Cuál es el masculino de «baronesa»?",["barones","barón","baronés"],1,"«Barones» es el plural de barón."],
     ["¿Cuál es la forma correcta?",["la calor","el calor","los calor"],1,"En castellano «calor» es masculino."],
     ["¿Cómo se forma el plural de «club»?",["clubes (o clubs)","clubos","club no tiene plural"],0,"Unas palabras extranjeras añaden -es (clubes) y otras -s (récords)."],
     ["¿Qué grupo concuerda bien?",["unas gatas negro","unos gatos negros","un gatos negro"],1,"Mismo género y número en todo el grupo."],
     ["¿Cuál es el femenino de «escritor»?",["escritora","escritriz","la escritor"],0,"Es de terminación variable: escritor, escritora, igual que chico, chica."],
     ["¿Qué forma es correcta en castellano?",["la costumbre","el costumbre","lo costumbre"],0,"En castellano «costumbre» es femenino, aunque en catalán sea «el costum»."],
     ["¿Cuál es el plural de «ley»?",["leys","leis","leyes"],2,"Igual que el libro: ley → leyes."]]},
 {id:"diccionario",practica:"fr-diccionario",esquema:{titol:"¿Qué palabra busco?",html:"<table><tr><th>Encuentro…</th><th>Busco…</th></tr><tr><td>canté, comíamos</td><td class='ex'>infinitivo: cantar, comer</td></tr><tr><td>niñas, bonitas</td><td class='ex'>masculino singular: niño, bonito</td></tr><tr><td>leones, felices</td><td class='ex'>singular: león, feliz</td></tr></table>"},frases:"fr-texto",ic:"📕",col:"#65a30d",titol:"Cómo usar el diccionario",font:"Tema 2 · p. 60",
  idea:"Cada palabra del diccionario es una entrada, y cada significado una acepción numerada. El contexto te dice cuál toca.",
  pts:["Sustantivos y adjetivos aparecen en <b>masculino singular</b>; los verbos, en <b>infinitivo</b> («corrían» → correr).",
   "Los diccionarios en línea buscan «por aproximación».","El <b>contexto</b> elige la acepción: «Siéntate en este banco» = asiento.",
   "Una buena <b>definición</b> empieza con un término general, dice sus características y <b>nunca repite la palabra</b> definida.",
   "El alfabeto tiene <b>27 letras</b>; <b>ch</b> y <b>ll</b> son dígrafos.","Abreviaturas: <b>m.</b> masculino, <b>f.</b> femenino, <b>adj.</b> adjetivo, <b>v.</b> verbo, <b>pl.</b> plural, <b>coloq.</b> coloquial."],
  truc:"Para buscar una palabra, devuélvela a casa: quítale el plural, el femenino y la conjugación. «Saltábamos» → saltar.",
  compte:"«Es cuando...» o «es donde...» no es una buena definición: empieza con una palabra general («Instrumento que...»).",
  fc:[["¿Qué es una entrada?","Cada palabra que se define en el diccionario."],["¿Qué es una acepción?","Cada uno de los significados numerados de una palabra."],["¿Cómo aparecen los verbos?","En infinitivo."],["¿Cuántas letras tiene el alfabeto?","27."],["¿Qué significa «m.»?","Masculino."]],
  q:[["Para buscar «corrían» en el diccionario buscas...",["corría","correr","corriendo"],1,"Los verbos aparecen en infinitivo."],
     ["Cada significado numerado de una palabra se llama...",["entrada","acepción","etimología"],1,"La entrada es la palabra; la acepción, cada significado."],
     ["¿Qué falla en «estación: es donde paran los trenes»?",["No empieza con un término general","Es demasiado corta","Repite la palabra estación"],0,"Mejor: «Lugar donde se detienen habitualmente los trenes»."],
     ["¿Cuántas letras tiene el alfabeto castellano?",["27","29","26"],0,"Ch y ll no son letras, son dígrafos."],
     ["¿Cómo aparece «guapas» en el diccionario?",["guapa","guapos","guapo"],2,"Los adjetivos aparecen en masculino singular."],
     ["«Siéntate en este banco.» ¿Qué te dice qué acepción de «banco» toca?",["El contexto","El orden alfabético","La abreviatura"],0,"El contexto elige la acepción: aquí, banco es un asiento."],
     ["¿Qué son «ch» y «ll»?",["Letras del alfabeto","Abreviaturas","Dígrafos"],2,"Son dígrafos: dos letras que suenan como una. Por eso el alfabeto tiene 27 letras."],
     ["¿Cuál es la mejor definición de «lápiz»?",["Es cuando escribes con un palo de madera","Instrumento de madera con una mina para escribir","Lápiz que sirve para escribir y dibujar"],1,"Empieza con un término general y no repite la palabra definida."]]},
 {id:"puntuacion",practica:"fr-puntua",esquema:{titol:"La coma: sí y no",html:"<div class='esq-col'><div style='background:#dcfce7'>✅ <b>Sí</b><br>vocativo: <i>Eduardo, ven</i><br>aclaración: <i>Mi abuelo, cansado, …</i><br>enumeración: <i>pan, leche y huevos</i></div><div style='background:#fee2e2'>❌ <b>No</b><br>entre sujeto y verbo<br>delante de la «y» final<br>detrás de «pero» + ¿?</div></div>"},frases:"fr-coma",ic:"✏️",col:"#16a34a",titol:"La coma y el punto y coma",font:"Tema 2 · p. 62",
  idea:"La coma separa ideas dentro de un enunciado; el punto y coma es una pausa mayor que la coma y menor que el punto.",
  pts:["Coma en <b>enumeraciones</b>: leche, cereales, fruta y pan.","Coma para encerrar <b>aclaraciones</b>: El público, harto de esperar, protestó.",
   "Coma tras una <b>circunstancia al principio</b>: A pesar de la lesión, siguió.","Coma que <b>sustituye a un verbo</b>: Yo saldré a las ocho; vosotros, más tarde.",
   "Coma con el <b>vocativo</b>: Por favor, Eduardo, acércame la sal. Y antes y después de <b>es decir, o sea, sin embargo</b>.",
   "<b>Punto y coma</b>: oraciones muy relacionadas, enumeraciones que ya llevan comas, y antes de <b>pero, sin embargo</b> si las oraciones son largas. Después, minúscula.",
   "Saludo de carta con <b>dos puntos</b>: Querido Ángel:"],
  truc:"Sujeto y verbo son inseparables: nunca una coma entre ellos. Y el vocativo va siempre abrazado por comas.",
  compte:"«Laura, ha venido» está mal: no se separa el sujeto del verbo. Y no va coma antes de la «y» de una enumeración.",
  fc:[["¿Qué es el vocativo?","El nombre de la persona a la que hablas, entre comas."],["¿Qué va tras «Querido Ángel» en una carta?","Dos puntos."],["¿Qué letra va después de un punto y coma?","Minúscula."],["¿Coma entre sujeto y verbo?","Nunca."],["«Yo saldré a las ocho; vosotros, más tarde.» ¿Qué hace la coma?","Sustituye al verbo."]],
  q:[["¿Qué frase está bien puntuada?",["Camarero un café, por favor.","Camarero, un café, por favor.","Camarero, un café por, favor."],1,"«Camarero» es un vocativo y «por favor» va separado."],
     ["¿Qué frase es incorrecta?",["Laura, ha venido.","Laura ha venido.","Laura, Pedro y Javier han venido."],0,"No se separa el sujeto del verbo con coma."],
     ["En una carta, tras «Querido Ángel» se escribe...",["coma","dos puntos","punto y coma"],1,"La coma en el saludo es un anglicismo."],
     ["«Mi hermano llegará el lunes; yo, el martes.» ¿Qué hace la coma de «yo, el martes»?",["Separa una enumeración","Sustituye al verbo «llegaré»","Separa un vocativo"],1,"Evita repetir el verbo."],
     ["¿Cuál es correcta?",["Pero, ¿de dónde vienes?","Pero ¿de dónde vienes?","Pero ¿de dónde, vienes?"],1,"Tras «pero» no va coma si viene una pregunta."],
     ["¿Qué enumeración está bien puntuada?",["Compré leche, pan, fruta, y huevos.","Compré leche pan, fruta y huevos.","Compré leche, pan, fruta y huevos."],2,"En una enumeración van comas, pero no antes de la «y»."],
     ["«Mi abuelo, cansado del viaje, se fue a dormir.» ¿Qué hacen las comas?",["Encierran una aclaración","Separan un vocativo","Sustituyen a un verbo"],0,"«Cansado del viaje» es una aclaración, y va entre comas."],
     ["¿Qué frase está bien escrita?",["Llovía mucho; nadie salió de casa.","Llovía mucho; Nadie salió de casa.","Llovía mucho. nadie salió de casa."],0,"Después del punto y coma va minúscula; después del punto, mayúscula."]]},
 {id:"noticia",practica:"mc-5w",esquema:{titol:"La pirámide invertida",html:"<table><tr><td style='background:#fde68a'>TITULAR · lo más importante</td></tr><tr><td style='background:#fef3c7'>ENTRADILLA · las 5 W: qué, quién, cuándo, dónde, por qué</td></tr><tr><td>CUERPO · de más a menos importante</td></tr></table>"},frases:"fr-noticia-lit",ic:"📰",col:"#0891b2",titol:"La noticia",font:"Tema 3 · p. 78",
  idea:"La noticia cuenta de forma objetiva un hecho de interés público y responde a qué, quién, dónde, cuándo, por qué y cómo.",
  pts:["Suele ir <b>firmada</b> por un periodista o una agencia y usa <b>fuentes</b> (testigos, administraciones, agencias).",
   "<b>Antetítulo</b>: sitúa el tema (no siempre está).","<b>Titular</b>: lo esencial en pocas palabras, y que llame la atención.",
   "<b>Entradilla</b>: los datos más importantes: las <b>5 W</b> (What, Who, Where, When, Why).",
   "<b>Cuerpo</b>: más datos y el <b>cómo</b> (hoW), en párrafos <b>de más a menos importante</b>. Las destacadas llevan foto."],
  truc:"La noticia es un embudo: arriba lo más gordo, abajo los detalles. 5 W + 1 H.",
  compte:"Las 5 W van en la entradilla; el cómo suele ir en el cuerpo.",
  fc:[["¿Qué parte responde a qué, quién, dónde, cuándo y por qué?","La entradilla."],["¿Qué parte resume lo esencial y llama la atención?","El titular."],["¿Cómo se ordenan los párrafos del cuerpo?","De más a menos importante."],["Las 5 W","What, Who, Where, When, Why."],["¿Qué son las fuentes?","De dónde sale la información: testigos, administraciones, agencias."]],
  q:[["¿Qué parte de la noticia responde a las 5 W?",["El titular","La entradilla","El antetítulo"],1,"La entradilla da los datos más importantes."],
     ["¿Cómo se ordenan los párrafos del cuerpo?",["De más a menos interés","De menos a más interés","Por orden alfabético"],0,"Si solo lees el principio, ya sabes lo importante."],
     ["¿Cómo cuenta los hechos una noticia?",["De forma objetiva","Dando la opinión del periodista","Inventando detalles"],0,"La noticia es objetiva."],
     ["En la noticia del libro, «CRISIS APÍCOLA EN PORTUGAL» es...",["el antetítulo","el cuerpo","la entradilla"],0,"Va encima del titular «La sequía se traga la miel»."],
     ["¿Qué parte de la noticia dice lo esencial en pocas palabras y llama la atención?",["El cuerpo","La entradilla","El titular"],2,"El titular es corto y llamativo."],
     ["¿En qué parte suele ir el «cómo» (la H de hoW)?",["En el cuerpo","En el titular","En el antetítulo"],0,"Las 5 W van en la entradilla; el cómo, en el cuerpo."],
     ["¿Qué son las fuentes de una noticia?",["Los tipos de letra del periódico","De dónde sale la información","Las fotos de la noticia"],1,"Testigos, administraciones o agencias: de ahí sale la información."],
     ["¿Qué parte de la noticia no siempre aparece?",["El titular","La entradilla","El antetítulo"],2,"El antetítulo sitúa el tema, pero no siempre está."]]},
 {id:"fake",practica:"clickbait",frases:"fr-noticia-lit",ic:"🕵️",col:"#0e7490",titol:"Noticias falsas y clickbait",font:"Tema 3 · p. 79",
  idea:"Una noticia falsa se crea con información falsa o deformada para engañar y manipular. La defensa: contrastar en medios serios.",
  pts:["Buscan un <b>beneficio económico o político</b>, influir en la opinión y a veces dañar la imagen de alguien.",
   "Se difunden sobre todo por las <b>redes sociales</b>.",
   "Pistas: es <b>anónima</b>, te pide que la <b>reenvíes</b>, está <b>mal escrita</b>, abusa de <b>MAYÚSCULAS</b> y ¡¡exclamaciones!!",
   "Para combatirlas: buscar la información en <b>medios de comunicación serios</b> y contrastarla.",
   "<b>Clickbait</b> o ciberanzuelo: titular exagerado que te hace pinchar y te lleva a otra cosa. Busca visitas y dinero con publicidad."],
  truc:"Detector A-R-F-M: Anónima, pide Reenviarla, tiene Faltas y MAYÚSCULAS. Si lo cumple, alarma.",
  compte:"Que algo sea muy impactante no lo hace verdad: las noticias falsas están hechas para sorprender.",
  fc:[["¿Para qué se crea una noticia falsa?","Para engañar y manipular, buscando dinero o poder."],["Dos pistas de una noticia falsa","Es anónima y pide que la reenvíes (también faltas y mayúsculas)."],["¿Cómo se combaten?","Contrastando en medios de comunicación serios."],["¿Qué es el clickbait?","Un titular exagerado para que pinches."],["¿Por dónde se difunden sobre todo?","Por las redes sociales."]],
  q:[["Te llega «¡¡¡MAÑANA NO HAY COLE!!! REENVÍALO». ¿Qué haces?",["Reenviarlo enseguida","Buscarlo en medios serios antes de creerlo","Creerlo porque está en mayúsculas"],1,"Mayúsculas, exclamaciones y «reenvíalo» son pistas de noticia falsa."],
     ["Las noticias falsas se crean...",["para entretener","para engañar y manipular","para informar mejor"],1,"Buscan un beneficio económico o político."],
     ["¿Qué es el clickbait?",["Un titular exagerado para que pinches","Una noticia de deportes","Una agencia de noticias"],0,"Busca visitas para ganar dinero con publicidad."],
     ["¿Cuál de estas es una pista de noticia falsa?",["Va firmada por un periodista","Es anónima","Cita fuentes oficiales"],1,"No dice de dónde viene."],
     ["¿Por dónde se difunden sobre todo las noticias falsas?",["Por los periódicos serios","Por las redes sociales","Por las agencias de noticias"],1,"Corren sobre todo por las redes sociales."],
     ["¿Qué busca el clickbait?",["Visitas y dinero con publicidad","Informar con datos contrastados","Ayudar a los lectores a ahorrar tiempo"],0,"Te hace pinchar para tener visitas y ganar dinero con la publicidad."],
     ["Una noticia te sorprende muchísimo. ¿Eso la hace verdadera?",["Sí, si es muy impactante","No: las falsas están hechas para sorprender","Sí, si la comparte mucha gente"],1,"Que algo impacte no lo hace verdad. ¡Contrasta siempre!"],
     ["¿Cuál es la mejor forma de combatir una noticia falsa?",["Contrastarla en medios serios","Reenviarla para avisar","Comentarla en las redes sociales"],0,"Hay que buscar la información en medios de comunicación serios."]]},
 {id:"lirica",practica:"fr-fragmentos",frases:"fr-noticia-lit",ic:"🎭",col:"#7c3aed",titol:"Los géneros literarios: lírica y teatro",font:"Tema 3 · p. 82",
  idea:"Hay tres grandes géneros: la lírica (poesía), la dramática (teatro) y la épica (narrativa).",
  pts:["<b>Lírica</b>: el autor expresa su mundo interior, sus <b>emociones y sentimientos</b>.",
   "<b>Lírica culta</b>: de autores cultos, transmitida por escrito. <b>Lírica popular</b>: anónima y oral, versos cortos y sencillos.",
   "<b>Dramática</b>: se escribe para ser <b>representada</b> por actores ante un público, con <b>diálogos</b> y <b>acotaciones</b> (gestos, vestuario, decorado).",
   "<b>Tragedia</b>: las pasiones llevan a un final desgraciado. <b>Comedia</b>: humor y final feliz. <b>Drama</b>: conflicto real, doloroso e intenso."],
  truc:"Lírica = Lo que siento. Dramática = Diálogo en un escenario. Épica = Érase una vez.",
  compte:"Las acotaciones no las dicen los actores: son las indicaciones del autor entre paréntesis.",
  fc:[["Los tres géneros literarios","Lírica, dramática y épica."],["¿Qué expresa la lírica?","Emociones y sentimientos."],["¿Qué son las acotaciones?","Indicaciones sobre gestos, movimientos, vestuario y decorado."],["Lírica popular","Anónima y transmitida de boca en boca."],["Teatro con final desgraciado","Tragedia."]],
  q:[["¿Qué son las acotaciones?",["Las indicaciones del autor sobre gestos, vestuario o decorado","Los versos de un poema","Los capítulos de una novela"],0,"Son propias del teatro."],
     ["Una obra de teatro con humor y final feliz es...",["una tragedia","una comedia","un drama"],1,"La tragedia acaba mal."],
     ["La lírica popular suele ser...",["anónima y oral","de autores cultos y escrita","siempre una novela"],0,"Se transmite de boca en boca."],
     ["¿Qué género expresa sobre todo emociones y sentimientos?",["La lírica","La dramática","La épica"],0,"Lírica = lo que siento."],
     ["¿Cuáles son los tres grandes géneros literarios?",["Cuento, novela y poema","Lírica, dramática y épica","Tragedia, comedia y drama"],1,"Lírica (poesía), dramática (teatro) y épica (narrativa)."],
     ["Una obra de teatro en la que las pasiones llevan a un final desgraciado es...",["una comedia","un drama","una tragedia"],2,"La tragedia acaba mal por culpa de las pasiones."],
     ["¿Para qué se escribe una obra dramática?",["Para que la representen actores","Para leerla en silencio en casa","Para expresar solo los sentimientos del autor"],0,"El teatro se escribe para ser representado ante un público."],
     ["¿Quién dice las acotaciones en una obra de teatro?",["Los actores, en voz alta","Nadie: son indicaciones del autor","El narrador, antes de cada escena"],1,"Las acotaciones no se dicen: indican gestos, vestuario o decorado."]]},
 {id:"narrativa",practica:"fr-fragmentos",frases:"fr-noticia-lit",ic:"🐉",col:"#9333ea",titol:"La narrativa: cuento, mito, leyenda y novela",font:"Tema 3 · p. 83",
  idea:"La narrativa cuenta hechos que les pasan a unos personajes en un tiempo y un lugar, y siempre hay un narrador.",
  pts:["Hoy se escribe en <b>prosa</b>; «épica» se reserva para textos antiguos en <b>verso</b>.",
   "<b>Cuento</b>: corto y sencillo, pocos personajes. Las <b>fábulas</b> tienen animales. Recopiladores: Grimm, Perrault, Andersen.",
   "<b>Mito</b>: dioses, héroes o monstruos que explican las <b>creencias</b> de un pueblo (Hércules, el Minotauro, Medusa).",
   "<b>Leyenda</b>: lugares, personajes o hechos <b>históricos</b> con elementos sobrenaturales (el Cid, Sant Jordi). Bécquer escribió las suyas.",
   "<b>Novela</b>: relato <b>extenso</b>, con muchos personajes, dividido en <b>capítulos</b> (policíaca, de terror, histórica, juvenil...)."],
  truc:"Mito = mandan los dioses. Leyenda = algo real + un toque mágico (Sant Jordi existió... el dragón, ya me dirás).",
  compte:"No confundas mito y leyenda: el mito va de dioses; la leyenda parte de algo real.",
  fc:[["¿Qué es una fábula?","Un cuento protagonizado por animales."],["Mito: ¿quién lo protagoniza?","Dioses, héroes o monstruos."],["Leyenda de Cataluña del libro","Sant Jordi."],["¿Cómo se divide una novela?","En capítulos."],["Recopiladores de cuentos populares","Grimm, Perrault, Andersen."]],
  q:[["Teseo y el Minotauro aparecen en...",["mitos","leyendas","fábulas"],0,"Son seres sobrenaturales de la mitología grecolatina."],
     ["La historia de Sant Jordi es...",["un mito","una leyenda","una novela"],1,"Parte de un personaje con elementos sobrenaturales."],
     ["Un cuento protagonizado por animales es...",["una fábula","una tragedia","una leyenda"],0,"Las fábulas suelen dejar una enseñanza."],
     ["¿Qué narración es más larga y se divide en capítulos?",["El cuento","La novela","La fábula"],1,"La novela es extensa y compleja."],
     ["Según el libro, ¿quién escribió sus propias leyendas?",["Bécquer","Andersen","Perrault"],0,"Bécquer escribió leyendas; Andersen y Perrault recopilaron cuentos."],
     ["Un mito sirve para...",["contar un hecho histórico real","explicar las creencias de un pueblo","dar una enseñanza protagonizada por animales"],1,"Los dioses y héroes del mito explican lo que creía un pueblo."],
     ["¿Cómo se escribe hoy la narrativa?",["En prosa","En verso","En diálogo con acotaciones"],0,"Hoy es en prosa; «épica» se reserva para textos antiguos en verso."],
     ["Grimm, Perrault y Andersen fueron...",["autores de novelas policíacas","recopiladores de cuentos","autores de leyendas en verso"],1,"Recogieron cuentos populares y los pusieron por escrito."]]},
 {id:"articulos",practica:"mc-determinantes",esquema:{titol:"Los determinantes",html:"<table><tr><th>Tipo</th><th>Ejemplos</th></tr><tr><td>Artículo</td><td>el, la, los, las, un, una</td></tr><tr><td>Demostrativo</td><td>este · ese · aquel</td></tr><tr><td>Posesivo</td><td>mi, tu, su, nuestro…</td></tr><tr><td>Numeral</td><td>tres, primer…</td></tr><tr><td>Indefinido</td><td>algún, varios…</td></tr><tr><td>Interrogativo / exclamativo</td><td>¿cuántos? ¡qué!</td></tr></table>"},frases:"fr-determinantes",ic:"🔤",col:"#2563eb",titol:"Los determinantes y los artículos",font:"Tema 3 · p. 88",
  idea:"El determinante va delante del sustantivo y lo concreta: «casa» es cualquiera; «mi casa» o «esta casa», una en concreto.",
  pts:["Si va <b>detrás</b> del nombre, <b>deja de ser determinante</b>.","Clases: artículos, demostrativos, posesivos, cuantificadores, relativos, interrogativos y exclamativos.",
   "<b>Artículo determinado</b> (algo conocido): el, la, lo, los, las. <b>Indeterminado</b> (algo nuevo): un, una, unos, unas.",
   "Femeninos con <b>a- tónica</b>: <b>el</b> aula, <b>un</b> aula; pero <b>las</b> aulas, <b>una</b> bonita aula.",
   "<b>Lo</b> + adjetivo: lo bueno, lo difícil. Contracciones: a + el = <b>al</b>; de + el = <b>del</b>.",
   "Los nombres de persona <b>no llevan artículo</b> en castellano (no «la Marta»); algunos lugares sí: el Teide, los Pirineos."],
  truc:"El determinante es el portero de la discoteca: siempre está delante de la puerta (el sustantivo).",
  compte:"El, la, los son artículos, no demostrativos. En el cuaderno se colaron artículos donde se pedían demostrativos y cuantificadores.",
  fc:[["Artículos determinados","El, la, lo, los, las."],["Artículos indeterminados","Un, una, unos, unas."],["¿Por qué «el aula»?","Por la a tónica (solo en singular)."],["a + el =","al"],["¿Dónde va el determinante?","Delante del sustantivo."]],
  q:[["¿Por qué decimos «el aula»?",["Porque aula es masculino","Por la a tónica del principio","Por error"],1,"En plural vuelve lo normal: las aulas."],
     ["¿Cuál de estos es un artículo indeterminado?",["los","unas","esta"],1,"Un, una, unos, unas."],
     ["«El» y «la» son...",["demostrativos","artículos","posesivos"],1,"Los demostrativos son este, ese, aquel."],
     ["De + el =",["del","de el siempre","dél"],0,"Volvió muy cansada del partido."],
     ["¿Qué es correcto en castellano?",["La Marta ha venido","Marta ha venido","El Marta ha venido"],1,"Los nombres de persona no llevan artículo."],
     ["Decimos «el aula». ¿Y en plural?",["los aulas","el aulas","las aulas"],2,"El «el» de la a tónica solo va en singular: en plural, las aulas."],
     ["¿Qué artículo usamos para algo nuevo, que nombramos por primera vez?",["El determinado","El indeterminado","El demostrativo"],1,"Un, una, unos, unas presentan algo nuevo."],
     ["«___ difícil es empezar.» ¿Qué artículo va delante del adjetivo?",["Lo","El","La"],0,"Lo + adjetivo: lo bueno, lo difícil."]]},
 {id:"demostrativos",practica:"mc-determinantes",esquema:{titol:"Tres distancias",html:"<table><tr><th>Cerca (aquí)</th><th>Medio (ahí)</th><th>Lejos (allí)</th></tr><tr><td class='ex'>este</td><td class='ex'>ese</td><td class='ex'>aquel</td></tr></table>"},frases:"fr-determinantes",ic:"👉",col:"#1d4ed8",titol:"Demostrativos y posesivos",font:"Tema 3 · p. 89",
  idea:"Los demostrativos sitúan cerca o lejos de quien habla; los posesivos dicen de quién es.",
  pts:["<b>Cercanía</b>: este, esta, estos, estas. <b>Distancia intermedia</b>: ese, esa, esos, esas. <b>Lejanía</b>: aquel, aquella, aquellos, aquellas.",
   "Detrás del nombre son <b>adjetivos</b> (el chico ese). <b>Esto, eso, aquello</b> son pronombres.",
   "<b>Posesivos determinantes</b> (delante): mi, tu, su, mis, tus, sus, nuestro/a/os/as, vuestro/a/os/as.",
   "Detrás o solos son <b>adjetivos</b>: un amigo <b>mío</b>, los zapatos son <b>tuyos</b>.",
   "<b>Cuyo, cuya</b>: determinantes relativo-posesivos (Ese chico, cuyo padre es médico...).",
   "Incorrecto: «detrás nuestro», «debajo suyo». Correcto: detrás de nosotros, alrededor suyo, al lado nuestro."],
  truc:"Este → aquí. Ese → ahí. Aquel → allí. Señálalo con el dedo mientras lo dices.",
  compte:"«Mi» va delante y es determinante; «mío» va detrás y es adjetivo.",
  fc:[["Demostrativo de lejanía","Aquel (aquella, aquellos, aquellas)."],["«El chico ese»: ¿qué es «ese»?","Adjetivo, porque va detrás."],["«Un amigo mío»: ¿qué es «mío»?","Adjetivo."],["¿Se dice «detrás nuestro»?","No: detrás de nosotros."],["¿Qué es «cuyo»?","Un determinante relativo-posesivo."]],
  q:[["«Pásame ___ vaso que tienes a tu lado.» ¿Qué demostrativo encaja?",["aquel","ese","este"],1,"A tu lado = distancia intermedia."],
     ["¿Cuál es un demostrativo?",["la","aquella","mi"],1,"La es artículo; mi es posesivo."],
     ["En «un amigo mío», «mío» es...",["determinante","adjetivo","artículo"],1,"Va detrás del sustantivo."],
     ["¿Qué expresión es incorrecta?",["detrás de nosotros","detrás nuestro","al lado nuestro"],1,"Los posesivos no acompañan a adverbios."],
     ["«¿Ves ___ montañas tan lejanas?»",["estas","aquellas","esas"],1,"Lejanía = aquel, aquella, aquellos, aquellas."],
     ["¿Cuál es un posesivo determinante?",["aquel","unos","nuestro"],2,"Nuestro dice de quién es algo. Aquel es demostrativo y unos, artículo."],
     ["En «Ese chico, cuyo padre es médico...», «cuyo» es...",["un demostrativo","un relativo-posesivo","un artículo"],1,"Cuyo y cuya son determinantes relativo-posesivos."],
     ["«___ libro que tengo en la mano es mío.» ¿Qué demostrativo encaja?",["Este","Ese","Aquel"],0,"En la mano = aquí = cercanía: este."]]},
 {id:"cuantificadores",practica:"fr-escucha",frases:"fr-determinantes",ic:"🔢",col:"#4f46e5",titol:"Cuantificadores, interrogativos y exclamativos",font:"Tema 3 · p. 90",
  idea:"Los cuantificadores dicen cuántos; los interrogativos preguntan y los exclamativos llaman la atención. Todos van delante del sustantivo.",
  pts:["<b>Numerales cardinales</b>: cantidad exacta (diez días). Hasta el 30 en una palabra (veintitrés); desde el 31, con «y» (treinta y seis).",
   "<b>No numerales</b>: cantidad imprecisa: <b>algún, bastante, mucho, poco, otro, varios</b>.",
   "Ordinales (primero), fraccionarios (medio) y multiplicativos (doble) <b>no son determinantes</b>.",
   "<b>Interrogativos y exclamativos</b> delante del sustantivo: ¿<b>Qué</b> hora es? ¡<b>Cuánta</b> gente!",
   "Sin sustantivo detrás son <b>pronombres</b> (¿Quién viene?) o <b>adverbios</b> (¿Dónde vas?).",
   "Al subrayarlos, solo la palabra que va justo delante del sustantivo: <b>nunca los verbos</b> (habéis, hemos)."],
  truc:"Mira justo detrás: si hay un sustantivo pegado, es determinante (¿qué hora?). Si no, es pronombre o adverbio (¿quién?, ¿dónde?).",
  compte:"En el cuaderno se subrayaron también los verbos («habéis», «hemos») y artículos. Solo la palabra que acompaña al sustantivo.",
  fc:[["Tres cuantificadores no numerales","Algún, mucho, poco (bastante, otro, varios)."],["¿Cómo se escribe 36?","Treinta y seis."],["¿Cómo se escribe 23?","Veintitrés."],["¿«Primero» es determinante?","No, es un ordinal."],["En «¿Cuántos goles habéis marcado?», ¿qué se subraya?","Solo «Cuántos»."]],
  q:[["En «¿Cuántos goles habéis marcado?», ¿cuál es el determinante interrogativo?",["Cuántos","habéis","goles"],0,"Va delante del sustantivo «goles». «Habéis» es un verbo."],
     ["¿Cuál es un cuantificador no numeral?",["bastante","la","primero"],0,"Indica una cantidad imprecisa."],
     ["¿Cómo se escribe el número 36?",["treinta i seis","treinta y seis","treinta seis"],1,"Desde el 31, en dos palabras con «y»."],
     ["En «¿Quién ha venido?», «quién» es...",["determinante","pronombre","artículo"],1,"No va delante de un sustantivo."],
     ["En «Algunas niñas juegan con otras compañeras», los cuantificadores no numerales son...",["Algunas y otras","niñas y compañeras","juegan y con"],0,"Los dos van delante de un sustantivo e indican cantidad imprecisa."],
     ["¿Cómo se escribe el número 23?",["veintitres","veinte y tres","veintitrés"],2,"Hasta el 30 va en una palabra, y veintitrés lleva tilde."],
     ["¿Qué clase de numeral es «primero»?",["Cardinal","Ordinal","Partitivo"],1,"«Primero» indica el orden: es un numeral ordinal."],
     ["En «¡Cuánta gente hay!», «cuánta» es un determinante...",["interrogativo","numeral","exclamativo"],2,"Va delante de «gente» y llama la atención con exclamación."]]},
 {id:"polisemia",practica:"polisemias",frases:"fr-polisemia-b",ic:"🔀",col:"#0f766e",titol:"Polisemia y monosemia",font:"Tema 3 · p. 92",
  idea:"Una palabra polisémica tiene varios significados y el contexto elige cuál; una monosémica tiene uno solo.",
  pts:["<b>Canguro</b>: animal, chaqueta con capucha, arnés para bebés y persona que cuida niños.",
   "<b>Puente</b>: el del río, el del dentista y los días de fiesta juntos.","<b>Monosémicas</b>: rinoceronte, abrelatas, litio.",
   "Verbos comodín como <b>hacer</b> o <b>dar</b> son polisémicos: mejor cambiarlos por uno preciso.",
   "Hizo una bufanda → <b>tejió</b>. Hacía poemas → <b>escribía</b>. Hizo dinero → <b>ganó</b>. Haré trece años → <b>cumpliré</b>."],
  truc:"Poli = muchos (polideportivo). Mono = uno (monociclo).",
  compte:"Al cambiar «hacer» por otro verbo, no vale volver a poner «hizo»: «hizo una bufanda» → tejió.",
  fc:[["¿Qué es una palabra polisémica?","La que tiene varios significados."],["Una palabra monosémica","Abrelatas (o rinoceronte, litio)."],["«Hizo una bufanda» → ","Tejió."],["«Mañana haré trece años» →","Cumpliré."],["Dos significados de «banco»","Asiento y entidad donde se guarda dinero (y grupo de peces)."]],
  q:[["«Un banco de peces pasó junto al barco.» ¿Qué significa «banco»?",["Asiento","Entidad bancaria","Conjunto de peces"],2,"El contexto (peces) decide el significado."],
     ["¿Qué palabra es monosémica?",["puente","abrelatas","canguro"],1,"Solo tiene un significado."],
     ["«Con la lana que le sobró, hizo una bufanda.» ¿Qué verbo es más preciso?",["hizo","tejió","dio"],1,"Volver a poner «hizo» no cambia nada."],
     ["«El mes que viene haré trece años.» Cambia «haré» por...",["cumpliré","construiré","escribiré"],0,"Los años se cumplen."],
     ["«Este año el puente de diciembre es largo.» ¿Qué significa «puente»?",["La construcción sobre un río","Los días de fiesta juntos","La pieza del dentista"],1,"El contexto (diciembre, largo) nos dice que son días de fiesta."],
     ["«Mi tía hacía poemas preciosos.» ¿Qué verbo es más preciso?",["escribía","construía","tejía"],0,"Los poemas se escriben."],
     ["¿Qué significa «poli-» en «polisémica»?",["uno","nuevo","muchos"],2,"Poli = muchos, como en polideportivo."],
     ["¿Qué palabra es polisémica?",["rinoceronte","canguro","litio"],1,"Canguro es un animal, una chaqueta, un arnés y la persona que cuida niños."]]},
 {id:"letrab",practica:"fr-byv",esquema:{titol:"Con b siempre",html:"<table><tr><td>-aba, -abas, -ábamos</td><td class='ex'>jugábamos</td></tr><tr><td>después de m</td><td class='ex'>ambulancia</td></tr><tr><td>verbos en -bir</td><td class='ex'>escribir (menos hervir, servir, vivir)</td></tr><tr><td>familia de probar</td><td class='ex'>aprobado</td></tr></table>"},frases:"fr-polisemia-b",ic:"🅱️",col:"#15803d",titol:"El uso de la b",font:"Tema 3 · p. 94",
  idea:"La b y la v suenan igual, así que necesitamos reglas para saber cuándo va b.",
  pts:["Después de <b>m</b>: cambio, ambulancia. Delante de <b>l, r</b> u otra consonante: tabla, brazo, objeto.",
   "Empiezan por <b>al-, ar-</b> (árbol) y por <b>bu-, bus-, bur-</b> (buscar, burbuja).",
   "Pretérito imperfecto de los verbos en <b>-ar</b> y del verbo <b>ir</b>: cantaba, <b>estábamos</b>, cantabas, iba.",
   "Verbos <b>haber, deber, beber, caber, saber</b>. Verbos en <b>-bir, -buir</b> (escribir, contribuir), <b>menos hervir, servir y vivir</b>.",
   "Familias de palabras: prueba → <b>probar, aprobado, aprobación</b>; gobierno → gobernar.",
   "Grabar (un vídeo) ≠ gravar (con un impuesto)."],
  truc:"Después de m, siempre b: la ambulancia hace un cambio. Rebeldes con v: hervir, servir y vivir. Y «-aba» siempre con b.",
  compte:"El catalán engaña: aprovat, govern, envernissar llevan v, pero es aprobado, gobierno, barnizar, jabalina. En el cuaderno salieron «estavamos» y «cantavas»: es estábamos y cantabas.",
  fc:[["¿Con b o con v: «esta_amos»?","Estábamos (con b y tilde)."],["Traduce «aprovat»","Aprobado."],["Traduce «govern»","Gobierno."],["Las tres excepciones de -bir","Hervir, servir y vivir."],["¿Por qué «ambulancia» va con b?","Porque después de m va b."],["Traduce «envernissar»","Barnizar."]],
  q:[["¿Cuál está bien escrita?",["estavamos","estábamos","estabamos"],1,"Imperfecto de un verbo en -ar: con b, y con tilde en «nosotros»."],
     ["¿Cómo se dice «aprovat» en castellano?",["aprovado","aprobado","aprovat"],1,"Prueba → probar → aprobado: toda la familia con b."],
     ["¿Cuál es la excepción de la regla de -bir?",["escribir","servir","recibir"],1,"Hervir, servir y vivir van con v."],
     ["¿Cómo se escribe «gavardina» en castellano?",["gavardina","gabardina","gaverdina"],1,"En castellano es con b."],
     ["¿Por qué «cambio» se escribe con b?",["Porque va después de m","Porque es un verbo","Porque empieza por ca-"],0,"Después de m siempre va b."],
     ["¿Cómo se escribe correctamente?",["vurbuja","burbuja","burvuja"],1,"Las palabras que empiezan por bu-, bus- y bur- van con b."],
     ["¿Por qué «tabla» se escribe con b?",["Porque va delante de l","Porque va después de m","Porque es un verbo en -bir"],0,"Delante de l y r va b: tabla, brazo."],
     ["¿Qué forma del verbo «deber» está bien escrita?",["devemos","debémos","debemos"],2,"El verbo deber se escribe con b, y «debemos» no lleva tilde."]]}
];
const OB=[
 {t:"El texto y sus propiedades",q:"Explica qué es un texto y cuáles son sus tres propiedades. Explica cada una con una frase y pon un ejemplo de conector.",p:["Mensaje oral o escrito con sentido completo","Adecuación: se adapta a quién lo recibe y a la intención","Coherencia: tema definido y orden lógico","Cohesión: partes unidas con conectores (ej.: sin embargo, es decir)"],
  m:"Un texto es un mensaje oral o escrito que tiene sentido completo. Tiene que ser adecuado, es decir, adaptarse a quién va dirigido. Tiene que ser coherente: tener un tema claro y un orden lógico. Y tiene que estar cohesionado: sus partes se unen con conectores como «sin embargo» o «es decir»."},
 {t:"Los tipos de textos",q:"Escribe los siete tipos de textos y pon un ejemplo de cada uno.",p:["Narrativo y descriptivo con ejemplo","Dialogado y expositivo con ejemplo","Argumentativo e instructivo con ejemplo","Predictivo con ejemplo"],
  m:"Narrativo, como un cuento; descriptivo, como el retrato de mi perro; dialogado, como una entrevista; expositivo, como mi libro de Naturales; argumentativo, como un artículo de opinión; instructivo, como una receta; y predictivo, como el pronóstico del tiempo."},
 {t:"El sustantivo y sus clases",q:"Explica la diferencia entre sustantivo propio y común, y entre individual y colectivo. Pon dos ejemplos de cada clase.",p:["Propio: ser único, con mayúscula","Común: cualquiera de una clase","Individual: uno solo en singular","Colectivo: un grupo en singular","Dos ejemplos correctos de cada clase"],
  m:"Un sustantivo propio nombra a un ser único y va con mayúscula, como Carmen o Tarragona. Un común nombra a cualquiera de una clase, como niña o ciudad. Un individual nombra a uno solo, como abeja o pino, y un colectivo nombra a un grupo en singular, como enjambre o pinar."},
 {t:"El sustantivo y sus clases",q:"Inventa una oración con un sustantivo propio, uno colectivo y uno abstracto. Di qué clase es cada uno y explica por qué «amistad» es abstracto.",p:["Oración correcta con los tres sustantivos","Clasifica bien el propio y el colectivo","Clasifica bien el abstracto","Amistad: es un sentimiento, no se puede ver ni tocar"],
  m:"«Lucía vio un rebaño de ovejas con mucha alegría.» Lucía es propio, rebaño es colectivo y alegría es abstracto. Amistad es abstracto porque es un sentimiento: no se puede ver ni tocar, solo se siente."},
 {t:"Género, número y concordancia",q:"Explica las tres formas de marcar el género de los sustantivos que nombran seres sexuados. Pon dos ejemplos de cada una.",p:["Terminación variable (chico/chica, actor/actriz)","Heterónimos: palabras distintas (caballo/yegua, hombre/mujer)","Invariables: lo marca el artículo (el/la pianista)","Dos ejemplos de cada"],
  m:"Algunos cambian la terminación, como chico y chica o actor y actriz. Otros son palabras totalmente distintas, los heterónimos, como caballo y yegua u hombre y mujer. Y otros no cambian y el género lo marca el artículo, como el pianista y la pianista o el testigo y la testigo."},
 {t:"La coma y el punto y coma",q:"Explica cuatro usos de la coma con un ejemplo de cada uno. Después explica para qué sirve el punto y coma.",p:["Cuatro usos de la coma bien explicados","Un ejemplo correcto de cada uso","Punto y coma: pausa mayor que la coma y menor que el punto","Un uso del punto y coma (oraciones relacionadas, enumeraciones con comas...)"],
  m:"La coma separa las palabras de una enumeración (leche, pan y fruta), encierra aclaraciones (El público, harto de esperar, protestó), separa el vocativo (Por favor, Eduardo, ven) y sustituye un verbo (Yo saldré a las ocho; tú, más tarde). El punto y coma es una pausa mayor que la coma y menor que el punto, y separa oraciones muy relacionadas."},
 {t:"La noticia",q:"Explica qué es una noticia y cuáles son sus partes. Di qué preguntas responde la entradilla.",p:["Texto periodístico objetivo sobre un hecho de interés público","Antetítulo, titular, entradilla y cuerpo","La entradilla responde qué, quién, dónde, cuándo y por qué","El cuerpo: más datos y el cómo, de más a menos importante"],
  m:"La noticia es un texto periodístico que cuenta de forma objetiva un hecho de interés público. Tiene antetítulo, titular, entradilla y cuerpo. La entradilla responde a qué, quién, dónde, cuándo y por qué, y el cuerpo da más datos y el cómo, de más a menos importante."},
 {t:"Noticias falsas y clickbait",q:"Explica qué es una noticia falsa y para qué se crea. Escribe dos pistas para reconocerla y qué debes hacer para comprobar si es cierta.",p:["Información falsa o deformada para engañar y manipular","Busca beneficio económico o político / dañar la imagen de alguien","Dos pistas: anónima, pide reenviarla, faltas, mayúsculas","Contrastar en medios de comunicación serios"],
  m:"Una noticia falsa tiene información que no es cierta o que se ha deformado para engañar y manipular a la gente. Se crea para ganar dinero o poder. Se reconoce porque suele ser anónima y te pide que la reenvíes. Para comprobarla hay que buscarla en medios serios y contrastarla."},
 {t:"La narrativa: cuento, mito, leyenda y novela",q:"Explica la diferencia entre un mito y una leyenda, con un ejemplo de cada uno. Después explica qué es una fábula.",p:["Mito: dioses, héroes o monstruos que explican creencias","Ejemplo de mito (Hércules, el Minotauro, Medusa)","Leyenda: hecho, lugar o personaje real con elementos sobrenaturales","Ejemplo de leyenda (Sant Jordi, el Cid)","Fábula: cuento con animales"],
  m:"Un mito está protagonizado por dioses, héroes o monstruos y explica las creencias de un pueblo, como Hércules. Una leyenda parte de un lugar, un personaje o un hecho real y le añade algo sobrenatural, como Sant Jordi. Una fábula es un cuento protagonizado por animales."},
 {t:"Demostrativos y posesivos",q:"Escribe los demostrativos de cercanía, distancia intermedia y lejanía. Explica por qué «este» es determinante en «este libro» pero «ese» es adjetivo en «el chico ese».",p:["Cercanía: este, esta, estos, estas","Intermedia: ese, esa, esos, esas","Lejanía: aquel, aquella, aquellos, aquellas","Delante del sustantivo es determinante; detrás, adjetivo"],
  m:"De cercanía: este, esta, estos, estas. De distancia intermedia: ese, esa, esos, esas. De lejanía: aquel, aquella, aquellos, aquellas. En «este libro» va delante del sustantivo y es determinante; en «el chico ese» va detrás y es adjetivo."},
 {t:"Cuantificadores, interrogativos y exclamativos",q:"En «¡Cuánta gente ha venido a la fiesta! Algunos amigos trajeron muchos regalos», escribe los determinantes y di de qué tipo es cada uno.",p:["Cuánta: exclamativo","la: artículo determinado","Algunos: cuantificador no numeral","muchos: cuantificador no numeral","No incluye verbos (ha venido, trajeron)"],
  m:"Cuánta es un determinante exclamativo, la es un artículo determinado, y algunos y muchos son cuantificadores no numerales. «Ha venido» y «trajeron» son verbos, no determinantes."},
 {t:"Polisemia y monosemia",q:"Explica qué es una palabra polisémica y qué es una monosémica, con un ejemplo de cada una. Después escribe dos oraciones con «banco» con significados distintos.",p:["Polisémica: varios significados; el contexto decide","Monosémica: un solo significado","Un ejemplo de cada","Dos oraciones con «banco» con significados distintos"],
  m:"Una palabra polisémica tiene varios significados y el contexto dice cuál es, como «puente». Una monosémica tiene uno solo, como «abrelatas». «Nos sentamos en un banco del parque.» «Mi madre ha ido al banco a sacar dinero.»"},
 {t:"El uso de la b",q:"Escribe cuatro reglas del uso de la b con dos ejemplos cada una. Explica por qué «aprobado» y «gobierno» se escriben con b aunque en catalán sean «aprovat» y «govern».",p:["Cuatro reglas correctas (tras m, bl/br, -aba, haber/deber..., -bir...)","Dos ejemplos de cada regla","Aprobado: familia de prueba/probar, con b","Gobierno: familia de gobernar, con b; el catalán no sirve de guía"],
  m:"Se escribe b después de m (cambio, ambulancia), delante de l y r (tabla, brazo), en el imperfecto de los verbos en -ar (cantaba, estábamos) y en los verbos en -bir menos hervir, servir y vivir (escribir, recibir). Aprobado va con b porque es de la familia de probar y prueba, y gobierno de la de gobernar. El catalán aquí nos engaña."}
];

